4606:     fn step2_test_sender_id_uses_public_key_not_identity_id() {
4607:         // STEP 2: Verify that when preparing a message, the sender_id is set to
4608:         // the public_key_hex (the actual encryption key) rather than identity_id
4609:         // (the blake3 hash). The recipient needs the public_key to decrypt.
4610:         let core = IronCore::new();
4611:         core.grant_consent();
4612:         core.initialize_identity().unwrap();
4613: 
4614:         let info = core.get_identity_info();
4615:         let my_public_key = info.public_key_hex.expect("public key");
4616:         let my_identity_id = info.identity_id.expect("identity id");
4617: 
4618:         // Verify they are different
4619:         assert_ne!(my_public_key, my_identity_id);
4620: 
4621:         // Add a test contact to enable sending
4622:         let contact = crate::store::Contact::new(
4623:             "test-peer".to_string(),
4624:             "1234567890abcdef1234567890abcdef1234567890abcdef1234567890abcdef".to_string(),
4625:         );
4626:         core.contact_manager.read().add(contact).unwrap();
4627: 
4628:         // Prepare a message (this would normally be sent to the peer)
4629:         // Note: prepare_message is not public, but we can verify the behavior through
4630:         // the identity info that gets used. The actual sender_id is embedded in the
4631:         // plaintext message by prepare_message_internal.
